// The `/triagedesk` slash command: today's queue, in one ephemeral line.
// Read-only. Approving or skipping a draft happens on the card itself or in
// the app, never from typed slash-command text.

import { NextResponse, type NextRequest } from "next/server";
import { readVerifiedSlackBody } from "@/app/_lib/slack/verify";
import { slackCredentials } from "@/app/_lib/slack/config";
import { getSlackInstallByTeam } from "@/app/_lib/slack/install";
import { adminSupabase } from "@/app/_lib/supabase/admin";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

async function queueCounts(userId: string): Promise<{ waiting: number; inFlight: number }> {
  const sb = adminSupabase();
  const [waiting, inFlight] = await Promise.all([
    sb
      .from("triagedesk_drafts")
      .select("id", { count: "exact", head: true })
      .eq("user_id", userId)
      .eq("status", "pending_review"),
    sb
      .from("triagedesk_drafts")
      .select("id", { count: "exact", head: true })
      .eq("user_id", userId)
      .in("status", ["queued", "sending"]),
  ]);
  return { waiting: waiting.count ?? 0, inFlight: inFlight.count ?? 0 };
}

export async function POST(req: NextRequest) {
  const creds = slackCredentials();
  const verified = await readVerifiedSlackBody(req, creds?.signingSecret);
  if (!verified.ok) return NextResponse.json({ error: verified.reason }, { status: 401 });

  const form = new URLSearchParams(verified.rawBody);
  const teamId = form.get("team_id");
  if (!teamId) return NextResponse.json({ response_type: "ephemeral", text: "No team id on this request." });

  const install = await getSlackInstallByTeam(teamId);
  if (!install) {
    return NextResponse.json({
      response_type: "ephemeral",
      text: "This workspace isn't connected to a TriageDesk account. Reconnect from the TriageDesk Rails settings.",
    });
  }

  const { waiting, inFlight } = await queueCounts(install.userId);
  const text =
    waiting === 0 && inFlight === 0
      ? "The queue is clear. Nothing is waiting on you right now."
      : [
          waiting > 0 ? `*${waiting}* waiting for your approval` : null,
          inFlight > 0 ? `*${inFlight}* approved and about to send` : null,
        ]
          .filter(Boolean)
          .join(", ") + ". <https://triagedesk.thecompound.tech/dashboard?view=queue|Open the desk>";

  return NextResponse.json({ response_type: "ephemeral", text });
}

